function validate([username, timestamp, website]) {
  const n = username.length;
  if (n < 3 || n > 50) return 'The log needs 3 to 50 entries.';
  if (timestamp.length !== n || website.length !== n) return 'The three arrays must have the same length.';
  const word = /^[a-z]{1,10}$/;
  if (username.some(u => typeof u !== 'string' || !word.test(u))) return 'Each username is 1 to 10 lowercase letters.';
  if (website.some(w => typeof w !== 'string' || !word.test(w))) return 'Each website is 1 to 10 lowercase letters.';
  if (timestamp.some(t => !Number.isInteger(t) || t < 1 || t > 1000000000)) return 'Each timestamp is an integer from 1 to 10^9.';
  const times = new Set();
  const counts = new Map();
  for (let i = 0; i < n; i++) {
    const key = username[i] + ' ' + timestamp[i];
    if (times.has(key)) return 'A user cannot have two visits at the same timestamp.';
    times.add(key);
    counts.set(username[i], (counts.get(username[i]) || 0) + 1);
  }
  if (![...counts.values()].some(c => c >= 3)) return 'At least one user must have 3 or more visits.';
  return null;
}

