function mostVisitedPattern(username, timestamp, website) {
  const order = username.map((_, i) => i);
  order.sort((a, b) => timestamp[a] - timestamp[b]);
  const visits = new Map();
  for (const i of order) {
    if (!visits.has(username[i])) {
      visits.set(username[i], []);
    }
    visits.get(username[i]).push(website[i]);
  }
  const score = new Map();
  for (const sites of visits.values()) {
    const seen = new Set();
    for (let i = 0; i < sites.length; i++) {
      for (let j = i + 1; j < sites.length; j++) {
        for (let k = j + 1; k < sites.length; k++) {
          seen.add(sites[i] + ' ' + sites[j] + ' ' + sites[k]);
        }
      }
    }
    for (const pattern of seen) {
      score.set(pattern, (score.get(pattern) || 0) + 1);
    }
  }
  let best = '';
  let bestScore = 0;
  for (const [pattern, count] of score) {
    if (count > bestScore || (count === bestScore && pattern < best)) {
      best = pattern;
      bestScore = count;
    }
  }
  return best.split(' ');
}

