function mostVisitedPattern(username, timestamp, website) {
  // Try every triple of known websites in lexicographic order and count the users that follow it.
  const users = [...new Set(username)];
  const histories = users.map(user => {
    const mine = [];
    for (let i = 0; i < username.length; i++) if (username[i] === user) mine.push([timestamp[i], website[i]]);
    for (let a = 1; a < mine.length; a++) for (let b = a; b > 0 && mine[b - 1][0] > mine[b][0]; b--) [mine[b - 1], mine[b]] = [mine[b], mine[b - 1]];
    return mine.map(pair => pair[1]);
  });
  const follows = (history, pattern) => {
    let matched = 0;
    for (const site of history) if (matched < 3 && site === pattern[matched]) matched++;
    return matched === 3;
  };
  const sites = [...new Set(website)].sort();
  let best = null, bestScore = -1;
  for (const first of sites) for (const second of sites) for (const third of sites) {
    const pattern = [first, second, third];
    const count = histories.filter(history => follows(history, pattern)).length;
    if (count > bestScore) { bestScore = count; best = pattern; }
  }
  return best;
}

