function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const userPool = ["ann", "bob", "cy", "dee", "eve", "fay", "gus", "hal", "ivy", "jo", "kim", "lee"];
  const sitePool = size === 'large'
    ? ["a", "ab", "b", "ba", "home", "homepage", "cart", "maps", "news", "shop", "mail", "z"]
    : ["a", "ab", "b", "ba", "c"];
  for (;;) {
    const n = size === 'large' ? 50 : 3 + Math.floor(rand() * 8);
    const userCount = size === 'large' ? 3 + Math.floor(rand() * 8) : 1 + Math.floor(rand() * 3);
    const siteCount = size === 'large' ? 3 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * 5);
    const users = userPool.slice(0, userCount);
    const sites = sitePool.slice(0, siteCount);
    const limit = size === 'large' ? 1000000000 : 100;
    const used = new Set();
    const timestamp = [];
    while (timestamp.length < n) {
      const t = 1 + Math.floor(rand() * limit);
      if (!used.has(t)) { used.add(t); timestamp.push(t); }
    }
    const username = Array.from({ length: n }, () => pick(users));
    const website = Array.from({ length: n }, () => pick(sites));
    const counts = {};
    for (const user of username) counts[user] = (counts[user] || 0) + 1;
    if (Object.values(counts).some(c => c >= 3)) return [username, timestamp, website];
  }
}
